parameters.jsCode:
var APP = 'https://friedking.vercel.app';
function clean(s) { return String(s == null ? '' : s).replace(/[\r\n\t]+/g, ' ').replace(/ {2,}/g, ' ').trim() || '-'; }
function money(n) { return 'Rs ' + Number(n || 0).toLocaleString('en-IN'); }
function wa(raw) {
  var p = String(raw || '').replace(/[^0-9]/g, '');
  if (p.length === 10) { return '91' + p; }
  if (p.length === 11 && p.charAt(0) === '0') { return '91' + p.substring(1); }
  return p;
}
function phone(raw) {
  var p = wa(raw);
  return p.length === 12 && p.slice(0, 2) === '91' ? '+91 ' + p.slice(2, 7) + ' ' + p.slice(7) : '+' + p;
}
var out = [];
$input.all().forEach(function (it) {
  var e = it.json;
  if (!e || !e.event_id) { return; }
  var o = e.order || {};
  var num = o.order_number || '';
  var type = o.order_type || '';
  var first = clean(String(e.customer_name || 'there').split(' ')[0]);
  var etype = e.event_type || 'order_status_changed';
  var notification = e.customer_notification || {};
  var notificationKind = notification.kind || '';
  var m = { event_id: e.event_id, to: wa(e.phone), kind: 'skip', mode: 'none', text: '', fallback: '', receipt_url: '',
            template: '', params: [], in_window: !!e.in_window, error: '' };

  if (etype === 'order_status_changed') {
    if (e.status === 'preparing' && notification.receipt !== false) {
      var mins = Number(e.prep_minutes) || 0;
      m.kind = 'receipt';
      m.text = '\u2705 *Order ' + num + ' confirmed!*' + (mins ? '\nReady in about ' + mins + ' minutes.' : '');
      var lines = (Array.isArray(o.items_json) ? o.items_json : []).map(function (i) { return '- ' + i.name + ' x' + i.quantity; }).join('\n');
      m.fallback = m.text + '\n\n' + lines + '\n*Total: ' + money(o.total) + '*';
      m.receipt_url = e.order_id ? APP + '/api/receipt?order=' + e.order_id : '';
      m.template = 'friedking_order_updates';
      var numOnly = String(num).replace(/\D/g, '') || String(num);
      var totalRound = String(Math.round(Number(o.total || 0)));
      m.named_params = {
        customer_name: first,
        order_number: numOnly,
        status: 'confirmed',
        total: totalRound,
        branch: 'Pandeshwar'
      };
      m.params = [first, numOnly, 'confirmed', totalRound, 'Pandeshwar'];
    } else if (e.status === 'cancelled') {
      m.kind = 'text';
      m.text = '\u274c Order ' + num + ' has been cancelled.' + (e.reason ? '\nReason: ' + e.reason : '') + '\nPlease message us if you need any help.';
    } else if (notificationKind === 'ready_for_pickup') {
      m.kind = 'text';
      m.text = '\uD83D\uDD14 Your Fried King order ' + num + ' is ready! Please collect it at the counter.';
    } else if (notificationKind === 'thank_you') {
      m.kind = 'text';
      m.text = 'Thank you for choosing Fried King!';
    }
  } else if (etype === 'order_created' && notificationKind === 'table_round_added') {
    m.kind = 'text';
    var roundLines = (Array.isArray(o.items_json) ? o.items_json : []).map(function (i) { return '- ' + i.name + ' x' + i.quantity; }).join('\n');
    m.text = '\uD83C\uDF7D Table ' + (notification.tableNumber || e.table_number || '') + ' - new round added!\n\n' + roundLines + '\n\nRound total: ' + money(notification.roundTotalPaise / 100) + '\nCurrent table total: ' + money(notification.tableRunningTotalPaise / 100) + '.';
  } else if (etype === 'table_invoice_requested') {
    m.kind = 'receipt';
    m.text = 'Thank you for dining with us at Fried King!\nYour bill for table ' + (e.table_number || '') + ' is attached. Visit us again soon.';
    m.fallback = 'Thank you for dining with us at Fried King!\nTable ' + (e.table_number || '') + ' total: ' + money(e.amount) + '. Visit us again soon.';
    m.receipt_url = e.session_id ? APP + '/api/receipt?session=' + e.session_id : (e.order_id ? APP + '/api/receipt?order=' + e.order_id : '');
    m.template = 'friedking_table_bill';
    m.params = [first, String(e.table_number || ''), money(e.amount)];
  } else if (etype === 'rider_assigned') {
    m.kind = 'rider'; m.mode = 'template'; m.template = 'friedking_rider_msg';
    m.payment_payload = 'fk_paid:' + e.order_id;
    var itemList = (Array.isArray(o.items_json) ? o.items_json : []).map(function (i) { return i.quantity + ' x ' + clean(i.name); }).join(', ');
    var addr = clean(o.address || '');
    if (o.pincode && addr.indexOf(String(o.pincode)) === -1) { addr += ' - ' + clean(o.pincode); }
    var amount = Number(e.amount || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
    var customerPhone = phone(e.customer_phone || o.customer_phone);   // gives "+91 77952 40605"
    var heading = '*New delivery ' + num + '*.\n\nCustomer: *' + clean(e.customer_name || 'Guest') + ',*\nPhone ' + customerPhone + '.\n\nAddress: ' + addr + '.\n\nItems: ';
    var ending = '.\n\n*Collect cash: Rs ' + amount + '.*\n\nTap the button below after you collect the payment.';
    var room = Math.max(0, 1024 - heading.length - ending.length);
    if (itemList.length > room) itemList = itemList.slice(0, Math.max(0, room - 3)) + '...';
    m.text = heading + itemList + ending;
    m.params = [num, clean(e.customer_name || 'Guest'), customerPhone, addr, itemList, amount];
  } else if (etype === 'customer_rider_assigned') {
    m.kind = 'text';
    m.text = '\uD83D\uDEF5 Your order ' + num + ' is on the way!\nDelivery partner: ' + clean(e.rider_name || '') + ' (+' + wa(e.rider_phone || '') + ')';
  }

  if (m.kind === 'receipt') { m.mode = m.in_window ? 'free' : 'template'; }
  else if (m.kind === 'text') { m.mode = m.in_window ? 'free' : 'none'; if (!m.in_window) { m.error = 'outside the 24-hour WhatsApp window: needs an approved template'; } }
  m.send = m.mode !== 'none' && m.kind !== 'skip';
  out.push({ json: m });
});
return out;

var m = $('Build Message').item.json;
var url = ($json && $json.error) ? '' : (m.receipt_url || '');
var outgoing = null;
var text = m.text;
var error = m.error;
if (m.send) {
  if (m.kind === 'rider') {
    var riderWindow = $json && $json.statusCode === 200 && $json.body === true;
    if (riderWindow) {
      outgoing = { type: 'interactive', interactive: { type: 'button', body: { text: m.text },
        action: { buttons: [{ type: 'reply', reply: { id: m.payment_payload, title: 'Payment collected' } }] } } };
    } else {
      outgoing = { type: 'template', template: { name: m.template, language: { code: 'en' }, components: [
        { type: 'body', parameters: m.params.map(function (p) { return { type: 'text', text: String(p) }; }) },
        { type: 'button', sub_type: 'quick_reply', index: '0', parameters: [{ type: 'payload', payload: m.payment_payload }] }
      ] } };
    }
  } else if (m.kind === 'receipt' && m.mode === 'free') {
    if (url) { outgoing = { type: 'image', image: { link: url, caption: m.text } }; }
    else { text = m.fallback; outgoing = { type: 'text', text: { body: m.fallback } }; }
  } else if (m.kind === 'receipt' && m.mode === 'template') {
    // customer has not messaged in 24 h (e.g. ordered on the website): approved template with the receipt as its image
    if (url) {
      var bodyParams = m.named_params ? [
        { type: 'text', parameter_name: 'customer_name', text: String(m.named_params.customer_name || 'Customer') },
        { type: 'text', parameter_name: 'order_number', text: String(m.named_params.order_number || '') },
        { type: 'text', parameter_name: 'status', text: String(m.named_params.status || 'confirmed') },
        { type: 'text', parameter_name: 'total', text: String(m.named_params.total || '0') },
        { type: 'text', parameter_name: 'branch', text: String(m.named_params.branch || 'Pandeshwar') }
      ] : m.params.map(function (p) { return { type: 'text', text: String(p) }; });

      outgoing = { type: 'template', template: { name: m.template, language: { code: 'en' }, components: [
        { type: 'header', parameters: [{ type: 'image', image: { link: url } }] },
        { type: 'body', parameters: bodyParams }] } };
    } else { error = 'receipt picture could not be made'; }
  } else if (m.kind === 'text') {
    outgoing = { type: 'text', text: { body: m.text } };
  }
}
return { json: { event_id: m.event_id, to: m.to, send: !!outgoing, outgoing: outgoing, text: text,
                 receipt_sent: !!(m.kind === 'receipt' && url), kind: m.kind, error: outgoing ? '' : error } };

parameters.jsonBody:
={{ (function () {
  var m = $('Build Outgoing').item.json;
  var sent = !!m.send && !!($json.id || $json.wamid) && !$json.error && $json.status !== 'failed';
  var ok = m.send ? sent : (m.error === '');
  var err = m.send ? (sent ? '' : JSON.stringify($json.error || $json).slice(0, 400)) : m.error;
  return JSON.stringify({ p_id: m.event_id, p_ok: ok, p_error: err, p_phone: sent ? '+' + m.to : null, p_message_id: (sent && m.kind === 'rider') ? ($json.wamid || $json.id) : undefined,
    p_text: sent ? (m.receipt_sent ? '[receipt] ' : '') + m.text : null });
})() }}
